<html lang="en">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>North & Finch | Modern retail essentials</title>
    <style>
      :root {
        color-scheme: light;
        --bg: #f8f5ef;
        --surface: #fffdf8;
        --surface-strong: #111827;
        --text: #18201d;
        --muted: #5f6d65;
        --accent: #a6462d;
        --accent-strong: #7a2e1d;
        --accent-soft: #f2d8cd;
        --line: #ded6c8;
        --focus: #164ed8;
        --shadow: 0 24px 60px rgb(24 32 29 / 14%);
        --radius-lg: 28px;
        --radius-md: 18px;
        --radius-sm: 12px;
        --container: 1180px;
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        background: var(--bg);
        color: var(--text);
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        line-height: 1.5;
      }

      img {
        display: block;
        max-width: 100%;
      }

      a {
        color: inherit;
        text-decoration-thickness: 0.08em;
        text-underline-offset: 0.22em;
      }

      a:hover {
        color: var(--accent-strong);
      }

      button,
      input {
        font: inherit;
      }

      :focus-visible {
        outline: 3px solid var(--focus);
        outline-offset: 4px;
      }

      @media (prefers-reduced-motion: no-preference) {
        html {
          scroll-behavior: smooth;
        }

        .product-card,
        .deal-card,
        .story-card,
        .button {
          transition: transform 180ms ease, box-shadow 180ms ease, background-color 180ms ease;
        }

        .product-card:hover,
        .deal-card:hover,
        .story-card:hover {
          transform: translateY(-4px);
        }
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        z-index: 10;
        transform: translateY(-160%);
        border-radius: 999px;
        background: var(--surface-strong);
        color: #ffffff;
        padding: 0.75rem 1rem;
        text-decoration: none;
      }

      .skip-link:focus {
        transform: translateY(0);
      }

      .container {
        width: min(100% - 2rem, var(--container));
        margin-inline: auto;
      }

      .site-header {
        position: sticky;
        top: 0;
        z-index: 5;
        border-bottom: 1px solid rgb(222 214 200 / 80%);
        background: rgb(248 245 239 / 92%);
        backdrop-filter: blur(18px);
      }

      .header-layout {
        display: grid;
        grid-template-columns: auto 1fr auto;
        align-items: center;
        gap: 1rem;
        padding-block: 1rem;
      }

      .brand {
        display: inline-flex;
        align-items: center;
        gap: 0.65rem;
        color: var(--text);
        font-weight: 800;
        letter-spacing: -0.03em;
        text-decoration: none;
      }

      .brand-mark {
        display: grid;
        min-width: 2.5rem;
        min-height: 2.5rem;
        place-items: center;
        border-radius: 50%;
        background: var(--surface-strong);
        color: #ffffff;
        font-size: 0.78rem;
        letter-spacing: 0.02em;
      }

      .primary-nav ul,
      .site-footer ul {
        display: flex;
        flex-wrap: wrap;
        justify-content: center;
        gap: 0.35rem 1.2rem;
        margin: 0;
        padding: 0;
        list-style: none;
      }

      .primary-nav a,
      .site-footer a:not(.brand) {
        color: var(--muted);
        font-weight: 700;
        text-decoration: none;
      }

      .cart-link {
        display: inline-flex;
        align-items: center;
        gap: 0.55rem;
        min-height: 2.75rem;
        border: 1px solid var(--line);
        border-radius: 999px;
        background: var(--surface);
        padding: 0.55rem 0.8rem 0.55rem 1rem;
        font-weight: 800;
        text-decoration: none;
      }

      .cart-count {
        display: grid;
        min-width: 1.75rem;
        min-height: 1.75rem;
        place-items: center;
        border-radius: 50%;
        background: var(--accent);
        color: #ffffff;
        font-size: 0.85rem;
      }

      .section {
        padding-block: clamp(3rem, 8vw, 6.5rem);
      }

      .hero {
        overflow: hidden;
        background:
          radial-gradient(circle at 82% 18%, rgb(166 70 45 / 23%), transparent 28rem),
          linear-gradient(135deg, #fffdf8 0%, #efe3d2 100%);
      }

      .hero-grid {
        display: grid;
        grid-template-columns: minmax(0, 1.05fr) minmax(18rem, 0.75fr);
        align-items: center;
        gap: clamp(2rem, 6vw, 5rem);
      }

      .hero-copy {
        max-width: 43rem;
      }

      .eyebrow,
      .product-category,
      .deal-tag,
      .story-meta {
        margin: 0 0 0.7rem;
        color: var(--accent-strong);
        font-size: 0.78rem;
        font-weight: 900;
        letter-spacing: 0.14em;
        text-transform: uppercase;
      }

      h1,
      h2,
      h3,
      p {
        margin-top: 0;
      }

      h1 {
        margin-bottom: 1.35rem;
        font-size: clamp(2.5rem, 7vw, 5.9rem);
        line-height: 0.94;
        letter-spacing: -0.08em;
      }

      h2 {
        margin-bottom: 0;
        font-size: clamp(2rem, 4vw, 3.4rem);
        line-height: 1;
        letter-spacing: -0.06em;
      }

      h3 {
        margin-bottom: 0.7rem;
        font-size: 1.35rem;
        line-height: 1.15;
        letter-spacing: -0.035em;
      }

      .hero-text {
        max-width: 37rem;
        color: var(--muted);
        font-size: clamp(1.05rem, 2vw, 1.25rem);
      }

      .hero-actions {
        display: flex;
        flex-wrap: wrap;
        gap: 0.85rem;
        margin-top: 2rem;
      }

      .button {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        min-height: 3rem;
        border: 1px solid transparent;
        border-radius: 999px;
        padding: 0.8rem 1.2rem;
        font-weight: 850;
        text-decoration: none;
        cursor: pointer;
      }

      .button-primary {
        background: var(--accent);
        color: #ffffff;
      }

      .button-primary:hover {
        background: var(--accent-strong);
        color: #ffffff;
      }

      .button-secondary {
        border-color: var(--line);
        background: var(--surface);
        color: var(--text);
      }

      .hero-card {
        min-height: 30rem;
        display: flex;
        flex-direction: column;
        justify-content: end;
        border: 1px solid rgb(255 255 255 / 58%);
        border-radius: var(--radius-lg);
        background:
          linear-gradient(180deg, transparent 0%, rgb(17 24 39 / 82%) 78%),
          url("https://images.unsplash.com/photo-1483985988355-763728e1935b?auto=format&fit=crop&w=1200&q=80") center / cover;
        color: #ffffff;
        padding: clamp(1.25rem, 4vw, 2rem);
        box-shadow: var(--shadow);
      }

      .hero-card p,
      .hero-card span {
        color: rgb(255 255 255 / 86%);
      }

      .hero-card strong {
        display: block;
        margin-bottom: 0.7rem;
        font-size: clamp(1.8rem, 4vw, 3rem);
        line-height: 1;
        letter-spacing: -0.06em;
      }

      .section-heading {
        margin-bottom: 2rem;
      }

      .section-heading-inline {
        display: flex;
        align-items: end;
        justify-content: space-between;
        gap: 1rem;
      }

      .product-grid {
        display: grid;
        grid-template-columns: repeat(3, minmax(0, 1fr));
        gap: 1rem;
        margin: 0;
        padding: 0;
        list-style: none;
      }

      .product-card,
      .deal-card,
      .story-card,
      .newsletter-panel {
        border: 1px solid var(--line);
        border-radius: var(--radius-lg);
        background: var(--surface);
        box-shadow: 0 12px 30px rgb(24 32 29 / 7%);
      }

      .product-card {
        height: 100%;
        overflow: hidden;
      }

      .product-card img {
        width: 100%;
        aspect-ratio: 4 / 3;
        object-fit: cover;
      }

      .product-card-body {
        display: flex;
        min-height: 17rem;
        flex-direction: column;
        padding: 1.25rem;
      }

      .product-card h3 a,
      .story-card h3 a {
        text-decoration: none;
      }

      .product-description {
        color: var(--muted);
      }

      .product-meta {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 1rem;
        margin-top: auto;
        padding-top: 1.2rem;
        font-weight: 900;
      }

      .add-to-cart {
        min-height: 2.7rem;
        border: 0;
        border-radius: 999px;
        background: var(--surface-strong);
        color: #ffffff;
        padding: 0.65rem 0.95rem;
        font-weight: 850;
        cursor: pointer;
      }

      .add-to-cart:hover {
        background: var(--accent-strong);
      }

      .deals {
        background: #efe7da;
      }

      .deals-grid {
        display: grid;
        grid-template-columns: 1.3fr 1fr 1fr;
        gap: 1rem;
      }

      .deal-card {
        padding: clamp(1.3rem, 3vw, 2rem);
      }

      .deal-card-featured {
        background: var(--surface-strong);
        color: #ffffff;
      }

      .deal-card-featured .deal-tag,
      .deal-card-featured p {
        color: rgb(255 255 255 / 82%);
      }

      .deal-card-featured .text-link {
        color: #ffffff;
      }

      .text-link {
        color: var(--accent-strong);
        font-weight: 900;
      }

      .editorial-grid {
        display: grid;
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 1rem;
      }

      .story-card {
        display: grid;
        grid-template-columns: minmax(11rem, 0.75fr) 1fr;
        gap: 1.25rem;
        overflow: hidden;
        padding: 1rem;
      }

      .story-card img {
        width: 100%;
        height: 100%;
        min-height: 16rem;
        border-radius: calc(var(--radius-lg) - 0.5rem);
        object-fit: cover;
      }

      .story-card p:last-child {
        color: var(--muted);
      }

      .newsletter {
        padding-top: 0;
      }

      .newsletter-panel {
        display: grid;
        grid-template-columns: 1fr 1fr;
        gap: 2rem;
        align-items: center;
        padding: clamp(1.35rem, 4vw, 2.5rem);
      }

      .newsletter-panel p {
        color: var(--muted);
      }

      .newsletter-form label {
        display: block;
        margin-bottom: 0.45rem;
        font-weight: 850;
      }

      .form-row {
        display: flex;
        gap: 0.7rem;
      }

      .form-row input {
        width: 100%;
        min-height: 3rem;
        border: 1px solid var(--line);
        border-radius: 999px;
        background: #ffffff;
        color: var(--text);
        padding: 0.8rem 1rem;
      }

      .form-row input:user-invalid {
        border-color: var(--accent-strong);
      }

      .newsletter-form p {
        margin: 0.7rem 0 0;
        font-size: 0.9rem;
      }

      .form-error {
        color: var(--accent-strong);
        font-weight: 800;
      }

      [hidden] {
        display: none !important;
      }

      .status-message {
        width: min(100% - 2rem, var(--container));
        min-height: 1.5rem;
        margin: -2rem auto 2rem;
        color: var(--muted);
        font-weight: 750;
      }

      .site-footer {
        border-top: 1px solid var(--line);
        background: var(--surface-strong);
        color: #ffffff;
        padding-block: 2rem;
      }

      .footer-layout {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 1.5rem;
      }

      .footer-brand {
        color: #ffffff;
      }

      .site-footer .brand-mark {
        background: #ffffff;
        color: var(--surface-strong);
      }

      .site-footer p,
      .site-footer a:not(.brand) {
        color: rgb(255 255 255 / 78%);
      }

      @media (max-width: 860px) {
        .header-layout,
        .hero-grid,
        .newsletter-panel {
          grid-template-columns: 1fr;
        }

        .primary-nav ul {
          justify-content: start;
        }

        .cart-link {
          justify-self: start;
        }

        .product-grid,
        .deals-grid,
        .editorial-grid {
          grid-template-columns: 1fr;
        }

        .story-card {
          grid-template-columns: 1fr;
        }

        .story-card img {
          min-height: 13rem;
        }

        .section-heading-inline,
        .footer-layout {
          align-items: start;
          flex-direction: column;
        }
      }

      @media (max-width: 520px) {
        .container {
          width: min(100% - 1rem, var(--container));
        }

        .section {
          padding-block: 2.5rem;
        }

        .hero-card {
          min-height: 22rem;
        }

        .form-row,
        .hero-actions {
          flex-direction: column;
        }

        .button,
        .add-to-cart,
        .form-row input {
          width: 100%;
        }
      }

      @media (forced-colors: active) {
        .site-header,
        .product-card,
        .deal-card,
        .story-card,
        .newsletter-panel,
        .cart-link,
        .button,
        .form-row input {
          border: 1px solid CanvasText;
          box-shadow: none;
        }

        .hero-card {
          border: 1px solid CanvasText;
          background: Canvas;
          color: CanvasText;
        }

        .hero-card p,
        .hero-card span {
          color: CanvasText;
        }
      }

    </style>
  </head>
  <body>
    <a class="skip-link" href="#maincontent">Skip to main content</a>

    <header class="site-header">
      <div class="container header-layout">
        <a class="brand" href="#maincontent" aria-label="North and Finch home">
          <span class="brand-mark" aria-hidden="true">N&F</span>
          <span>North &amp; Finch</span>
        </a>

        <nav class="primary-nav" aria-label="Primary">
          <ul>
            <li><a href="#featured">New arrivals</a></li>
            <li><a href="#deals">Deals</a></li>
            <li><a href="#editorial">Journal</a></li>
            <li><a href="#newsletter">Community</a></li>
          </ul>
        </nav>

        <a class="cart-link" href="#featured" aria-label="View cart, 0 items">
          Cart <span class="cart-count" aria-hidden="true">0</span>
        </a>
      </div>
    </header>

    <main id="maincontent" tabindex="-1">
      <section class="hero section">
        <div class="container hero-grid">
          <div class="hero-copy">
            <p class="eyebrow">Spring edit 2026</p>
            <h1>Elevated everyday goods for home, style, and travel.</h1>
            <p class="hero-text">
              Discover considered essentials from a modern retail house: tactile homewares,
              premium wardrobe staples, and practical pieces made to move with you.
            </p>
            <div class="hero-actions">
              <a class="button button-primary" href="#featured">Shop featured products</a>
              <a class="button button-secondary" href="#editorial">Read the edit</a>
            </div>
          </div>

          <aside class="hero-card" aria-labelledby="weekender-heading">
            <p>Limited drop</p>
            <strong id="weekender-heading">The City Weekender Set</strong>
            <span>Save 20% when you bundle travel-ready apparel and accessories.</span>
          </aside>
        </div>
      </section>

      <section class="section" id="featured" aria-labelledby="featured-heading">
        <div class="container">
          <div class="section-heading">
            <p class="eyebrow">Curated picks</p>
            <h2 id="featured-heading">Featured products</h2>
          </div>

          <ul class="product-grid" aria-label="Featured products">
            <li>
              <article class="product-card" id="linen-utility-overshirt">
                <img src="https://images.unsplash.com/photo-1515886657613-9f3515b0c78f?auto=format&fit=crop&w=900&q=80" alt="Model wearing a neutral linen overshirt">
                <div class="product-card-body">
                  <p class="product-category">Apparel</p>
                  <h3><a href="#linen-utility-overshirt">Linen Utility Overshirt</a></h3>
                  <p class="product-description">A relaxed layer with corozo buttons and oversized patch pockets.</p>
                  <div class="product-meta">
                    <span>$128</span>
                    <button type="button" class="add-to-cart" data-product="Linen Utility Overshirt" aria-label="Add to cart: Linen Utility Overshirt">Add to cart</button>
                  </div>
                </div>
              </article>
            </li>
            <li>
              <article class="product-card" id="oak-canvas-lounge-chair">
                <img src="https://images.unsplash.com/photo-1524758631624-e2822e304c36?auto=format&fit=crop&w=900&q=80" alt="Minimal lounge chair beside a wood side table in a bright room">
                <div class="product-card-body">
                  <p class="product-category">Home</p>
                  <h3><a href="#oak-canvas-lounge-chair">Oak &amp; Canvas Lounge Chair</a></h3>
                  <p class="product-description">Low-profile comfort with FSC-certified oak and removable canvas covers.</p>
                  <div class="product-meta">
                    <span>$420</span>
                    <button type="button" class="add-to-cart" data-product="Oak & Canvas Lounge Chair" aria-label="Add to cart: Oak & Canvas Lounge Chair">Add to cart</button>
                  </div>
                </div>
              </article>
            </li>
            <li>
              <article class="product-card" id="commuter-leather-pack">
                <img src="https://images.unsplash.com/photo-1523275335684-37898b6baf30?auto=format&fit=crop&w=900&q=80" alt="Tan leather backpack with small travel accessories">
                <div class="product-card-body">
                  <p class="product-category">Travel</p>
                  <h3><a href="#commuter-leather-pack">Commuter Leather Pack</a></h3>
                  <p class="product-description">A structured carryall with laptop storage and recycled cotton lining.</p>
                  <div class="product-meta">
                    <span>$216</span>
                    <button type="button" class="add-to-cart" data-product="Commuter Leather Pack" aria-label="Add to cart: Commuter Leather Pack">Add to cart</button>
                  </div>
                </div>
              </article>
            </li>
          </ul>
        </div>
      </section>

      <section class="deals section" id="deals" aria-labelledby="deals-heading">
        <div class="container">
          <div class="section-heading">
            <p class="eyebrow">Worth the rush</p>
            <h2 id="deals-heading">Fresh deals</h2>
          </div>

          <div class="deals-grid">
            <article class="deal-card deal-card-featured" id="tableware-sale">
              <p class="deal-tag">48-hour offer</p>
              <h3>30% off tableware sets</h3>
              <p>Build a hosting-ready table with ceramic dinnerware, glassware, and woven linens.</p>
              <a class="text-link" href="#tableware-sale">Shop the tableware sale</a>
            </article>

            <article class="deal-card" id="basics-bundle">
              <p class="deal-tag">Bundle</p>
              <h3>Buy 2 basics, get 1 free</h3>
              <p>Mix organic cotton tees, ribbed tanks, and everyday socks.</p>
              <a class="text-link" href="#basics-bundle">Build your basics bundle</a>
            </article>

            <article class="deal-card">
              <p class="deal-tag">Members</p>
              <h3>Free shipping over $75</h3>
              <p>Join the list for early access, member pricing, and complimentary returns.</p>
              <a class="text-link" href="#newsletter">Join for free shipping</a>
            </article>
          </div>
        </div>
      </section>

      <section class="section" id="editorial" aria-labelledby="editorial-heading">
