      const cartLink = document.querySelector(".cart-link");
      const cartCount = document.querySelector(".cart-count");
      const statusMessage = document.querySelector(".status-message");
      const addToCartButtons = document.querySelectorAll(".add-to-cart");
      const newsletterForm = document.querySelector(".newsletter-form");
      const emailInput = document.querySelector("#email");
      const emailError = document.querySelector("#email-error");

      let cartItems = 0;

      function announce(message) {
        statusMessage.textContent = message;
      }

      function setEmailError(message) {
        emailInput.setAttribute("aria-invalid", "true");
        emailError.textContent = message;
        emailError.hidden = false;
      }

      function clearEmailError() {
        emailInput.removeAttribute("aria-invalid");
        emailError.textContent = "";
        emailError.hidden = true;
      }

      addToCartButtons.forEach((button) => {
        button.addEventListener("click", () => {
          const productName = button.dataset.product;
          cartItems += 1;
          cartCount.textContent = cartItems;
          cartLink.setAttribute("aria-label", `View cart, ${cartItems} ${cartItems === 1 ? "item" : "items"}`);
          announce(`${productName} added to cart. Cart now has ${cartItems} ${cartItems === 1 ? "item" : "items"}.`);
        });
      });

      emailInput.addEventListener("input", () => {
        if (emailInput.validity.valid) {
          clearEmailError();
        }
      });

      newsletterForm.addEventListener("submit", (event) => {
        event.preventDefault();

        if (!emailInput.validity.valid) {
          setEmailError("Error: Enter a valid email address, such as name@example.com.");
          announce("Enter a valid email address to sign up.");
          emailInput.focus();
          return;
        }

        announce(`Thanks. ${emailInput.value} is signed up for North & Finch updates.`);
        newsletterForm.reset();
        clearEmailError();
      });

    </script>
